# schematic: geometry of the task and the quantities delta and lambda
import numpy as np, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
plt.rcParams.update({'font.family':'DejaVu Serif','font.size':8})
fig,ax=plt.subplots(1,2,figsize=(6.6,2.7),gridspec_kw={'width_ratios':[1,1.25]})
a=ax[0]; t=np.linspace(0,2*np.pi,300); a.plot(np.cos(t),np.sin(t),color='k',lw=1)
for ang in (0,90): a.plot([-1.25*np.cos(np.radians(ang)),1.25*np.cos(np.radians(ang))],[-1.25*np.sin(np.radians(ang)),1.25*np.sin(np.radians(ang))],color='0.35',lw=0.8)
for ang in (45,135): a.plot([-1.2*np.cos(np.radians(ang)),1.2*np.cos(np.radians(ang))],[-1.2*np.sin(np.radians(ang)),1.2*np.sin(np.radians(ang))],color='0.35',lw=0.8,ls='--')
th=np.radians(12); a.plot(np.cos(th),np.sin(th),'o',color='k',ms=5); a.text(1.10,0.16,'target $\\theta$',fontsize=7.5,va='center')
arc=np.radians(np.linspace(12,45,30)); a.plot(0.55*np.cos(arc),0.55*np.sin(arc),color='#c0392b',lw=1.3); a.text(0.27,0.10,'$\\delta$',color='#c0392b',fontsize=9)
a.annotate('',xy=(1.13*np.cos(np.radians(30)),1.13*np.sin(np.radians(30))),xytext=(1.13*np.cos(np.radians(13)),1.13*np.sin(np.radians(13))),arrowprops=dict(arrowstyle='->',color='#2471a3',lw=1.6,connectionstyle='arc3,rad=0.2'))
a.text(1.18,0.50,'mean response',color='#2471a3',fontsize=7,va='center')
a.text(1.28,-0.03,'$0^\\circ$',fontsize=7.5,va='center'); a.text(-0.06,1.30,'$90^\\circ$',fontsize=7.5); a.text(0.92,0.98,'diagonal ($45^\\circ$)',fontsize=7); a.text(-1.5,-1.42,'solid: cardinal axes; dashed: diagonals',fontsize=6.8)
a.set_xlim(-1.45,2.25); a.set_ylim(-1.5,1.5); a.set_aspect('equal'); a.axis('off'); a.set_title('a',loc='left',fontsize=10,fontweight='bold')
b=ax[1]; x=np.linspace(-180,180,721); d=np.mod(x,90)-45; b.plot(x,-0.13*d,color='k',lw=1.2,label='$-\\lambda\\,\\delta(\\theta)$, $\\lambda=0.13$')
b.axhline(0,color='0.6',lw=0.6)
for v in (-180,-90,0,90,180): b.axvline(v,color='0.35',lw=0.6)
for v in (-135,-45,45,135): b.axvline(v,color='0.35',lw=0.6,ls='--')
b.set_xticks([-180,-90,0,90,180]); b.set_xlabel('target angle $\\theta$, deg'); b.set_ylabel('mean error, deg'); b.legend(frameon=False,fontsize=7,loc='upper right'); b.set_ylim(-8,12)
b.spines['top'].set_visible(False); b.spines['right'].set_visible(False); b.set_title('b',loc='left',fontsize=10,fontweight='bold')
fig.tight_layout(w_pad=1.5); fig.savefig('figE0.pdf'); print('ok')
